// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {IHooks} from "v4-core/src/interfaces/IHooks.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {Currency} from "v4-core/src/types/Currency.sol";

import {MemeToken} from "../../src/MemeToken.sol";
import {ClogMarket} from "../ClogMarket.sol";
import {ClogGenuineMath} from "./ClogGenuineMath.sol";
import {ClogGenuineLiquidityHook} from "./ClogGenuineLiquidityHook.sol";

interface ITickerNFTGenuinePublic {
    function mint(address to, uint256 tokenId) external;
}

interface IEligibilityGenuinePublic {
    function nextTokenId() external view returns (uint256);
    function registerToken(address market) external returns (uint256 tokenId);
}

/// @title ClogGenuinePublicRegistry
/// @notice Final public launch shell for the already-proven Genuine-V4 execution architecture.
///
/// Public launch policy:
/// - immutable launchStartTime: reveals cannot launch a ticker before the official countdown ends
/// - commit/reveal ticker claiming
/// - 2-10 ASCII letters, normalized to uppercase
/// - CLOG reserved
/// - ticker uniqueness
/// - maximum 7,777 public tickers
/// - exactly 0.002 ETH launch fee, 100% to Safe
/// - fixed Genuine-V4 tickSpacing = 1
///
/// The AMM/economic launch core intentionally matches ClogGenuineRegistry:
/// MemeToken -> ClogMarket -> Eligibility registration -> Genuine hook/pool -> token-only launch.
/// There is deliberately NO unrestricted raw launch() function.
contract ClogGenuinePublicRegistry is ReentrancyGuard {
    uint256 public constant MAX_PUBLIC_TICKERS = 7_777;
    uint256 public constant LAUNCH_PRICE = 0.002 ether;

    uint256 public constant MIN_TICKER_LENGTH = 2;
    uint256 public constant MAX_TICKER_LENGTH = 10;
    uint256 public constant MIN_REVEAL_DELAY = 60;
    uint256 public constant REVEAL_WINDOW = 1 days;

    int24 public constant TICK_SPACING = 1;

    bytes32 public constant RESERVED_CLOG_KEY = keccak256(bytes("CLOG"));

    address public immutable configurator;
    address public immutable safe;
    address public immutable tickerNFT;
    address public immutable multisig;
    address public immutable eligibilityRegistry;

    uint256 public immutable virtualEthSeed;
    uint256 public immutable bufferMultiplierBps;

    /// @notice Unix timestamp at which official public reveals become possible.
    ///         Immutable: nobody can move launch earlier or later after deployment.
    uint256 public immutable launchStartTime;

    IPoolManager public poolManager;
    ClogGenuineLiquidityHook public hook;
    address public rewardVault;

    uint256 public publicTickerCount;

    mapping(bytes32 => uint256) public commitTimestamp;
    mapping(bytes32 => bool) public tickerKeyTaken;

    mapping(uint256 => string) public tickerOf;
    mapping(uint256 => address) public marketOf;
    mapping(uint256 => address) public tokenOf;

    event Committed(address indexed sender, bytes32 commitHash);
    event V4InfrastructureConfigured(
        address indexed poolManager,
        address indexed hook,
        address indexed rewardVault
    );
    event Launched(
        address indexed sender,
        uint256 indexed tokenId,
        string ticker,
        address market,
        address token,
        uint256 fee
    );

    error NotConfigurator();
    error AlreadyConfigured();
    error ZeroAddress();
    error InvalidLaunchStart();
    error LaunchNotStarted(uint256 launchStartTime);
    error NotConfigured();
    error AlreadyCommitted();
    error InvalidTickerLength();
    error InvalidTickerCharacter();
    error ReservedTicker();
    error TickerTaken();
    error NoMatchingCommitment();
    error RevealTooEarly();
    error RevealExpired();
    error WrongFee();
    error PublicTickerCapReached();
    error EligibilityTokenIdMismatch(uint256 expected, uint256 actual);
    error FeeTransferFailed();

    constructor(
        address safe_,
        address tickerNFT_,
        address multisig_,
        address eligibilityRegistry_,
        uint256 virtualEthSeed_,
        uint256 bufferMultiplierBps_,
        uint256 launchStartTime_
    ) {
        if (
            safe_ == address(0)
                || tickerNFT_ == address(0)
                || multisig_ == address(0)
                || eligibilityRegistry_ == address(0)
        ) revert ZeroAddress();

        // Production is intentionally deployed BEFORE the countdown ends.
        if (launchStartTime_ <= block.timestamp) revert InvalidLaunchStart();

        configurator = msg.sender;
        safe = safe_;
        tickerNFT = tickerNFT_;
        multisig = multisig_;
        eligibilityRegistry = eligibilityRegistry_;
        virtualEthSeed = virtualEthSeed_;
        bufferMultiplierBps = bufferMultiplierBps_;
        launchStartTime = launchStartTime_;
    }

    /// @notice Compatibility/readability getter: EligibilityRegistry is the only token-ID
    ///         counter. There is deliberately no second mutable counter in this Registry.
    function nextTokenId() external view returns (uint256) {
        return IEligibilityGenuinePublic(eligibilityRegistry).nextTokenId();
    }

    /// @notice One-shot Genuine-V4 infrastructure wiring.
    function setV4Infrastructure(
        address pm,
        address hook_,
        address vault
    ) external {
        if (msg.sender != configurator) revert NotConfigurator();

        if (
            address(poolManager) != address(0)
                || address(hook) != address(0)
                || rewardVault != address(0)
        ) revert AlreadyConfigured();

        if (pm == address(0) || hook_ == address(0) || vault == address(0)) {
            revert ZeroAddress();
        }

        poolManager = IPoolManager(pm);
        hook = ClogGenuineLiquidityHook(payable(hook_));
        rewardVault = vault;

        // Hook accepts this once from its immutable Registry.
        hook.setRewardVault(vault);

        emit V4InfrastructureConfigured(pm, hook_, vault);
    }

    /// @notice Commitment may be made before the official launch timestamp.
    ///         This lets the UI prepare users during the countdown while ZERO ticker
    ///         can actually launch before launchStartTime.
    function commit(bytes32 commitHash) external {
        if (commitTimestamp[commitHash] != 0) revert AlreadyCommitted();

        commitTimestamp[commitHash] = block.timestamp;
        emit Committed(msg.sender, commitHash);
    }

    /// @notice Reveal + deploy + initialize + mint atomically.
    function reveal(
        string calldata ticker,
        bytes32 salt
    ) external payable nonReentrant returns (uint256 tokenId) {
        if (block.timestamp < launchStartTime) {
            revert LaunchNotStarted(launchStartTime);
        }

        if (address(poolManager) == address(0) || address(hook) == address(0)) {
            revert NotConfigured();
        }

        string memory normalized = _normalize(ticker);
        bytes32 tickerKey = keccak256(bytes(normalized));

        if (tickerKey == RESERVED_CLOG_KEY) revert ReservedTicker();
        if (tickerKeyTaken[tickerKey]) revert TickerTaken();

        bytes32 commitHash =
            keccak256(abi.encode(msg.sender, tickerKey, salt));

        uint256 committedAt = commitTimestamp[commitHash];

        if (committedAt == 0) revert NoMatchingCommitment();

        if (block.timestamp < committedAt + MIN_REVEAL_DELAY) {
            revert RevealTooEarly();
        }

        if (
            block.timestamp
                > committedAt + MIN_REVEAL_DELAY + REVEAL_WINDOW
        ) {
            revert RevealExpired();
        }

        if (msg.value != LAUNCH_PRICE) revert WrongFee();

        if (publicTickerCount >= MAX_PUBLIC_TICKERS) {
            revert PublicTickerCapReached();
        }

        // State is marked before external calls; any failure below reverts the
        // entire transaction, including these changes.
        delete commitTimestamp[commitHash];
        tickerKeyTaken[tickerKey] = true;
        publicTickerCount++;

        address market;
        address token;

        (tokenId, market, token) = _launchMeme(normalized);

        tickerOf[tokenId] = normalized;
        marketOf[tokenId] = market;
        tokenOf[tokenId] = token;

        // Ticker ownership and therefore fee rights belong to launcher.
        ITickerNFTGenuinePublic(tickerNFT).mint(msg.sender, tokenId);

        // 100% of launch fee goes to Safe.
        // Registry retains zero; WinnerPot gets zero launch fee.
        (bool ok,) = safe.call{value: LAUNCH_PRICE}("");
        if (!ok) revert FeeTransferFailed();

        emit Launched(
            msg.sender,
            tokenId,
            normalized,
            market,
            token,
            LAUNCH_PRICE
        );
    }

    function _launchMeme(
        string memory normalized
    )
        internal
        returns (
            uint256 tokenId,
            address marketAddress,
            address tokenAddress
        )
    {
        MemeToken token =
            new MemeToken(normalized, normalized, address(this));

        tokenAddress = address(token);

        // EligibilityRegistry is the sole token-ID source of truth.
        tokenId =
            IEligibilityGenuinePublic(eligibilityRegistry).nextTokenId();

        ClogMarket market = new ClogMarket(
            address(hook),
            tokenAddress,
            tickerNFT,
            tokenId,
            multisig,
            virtualEthSeed,
            bufferMultiplierBps,
            eligibilityRegistry
        );

        marketAddress = address(market);

        // Mint/lock the 1B token supply to the real market.
        token.setMarket(marketAddress);

        // Atomic Eligibility registration. The permanent tokenRegistrar
        // authorization ensures nobody else can consume an ID.
        uint256 registeredId =
            IEligibilityGenuinePublic(eligibilityRegistry)
                .registerToken(marketAddress);

        if (registeredId != tokenId) {
            revert EligibilityTokenIdMismatch(tokenId, registeredId);
        }

        market.grantHookApprovals(address(poolManager));

        PoolKey memory key = PoolKey({
            currency0: Currency.wrap(address(0)),
            currency1: Currency.wrap(tokenAddress),
            fee: 0,
            tickSpacing: TICK_SPACING,
            hooks: IHooks(address(hook))
        });

        // Same Genuine-V4 launch sequence already proven by the canary.
        hook.registerPool(key, marketAddress, virtualEthSeed);

        uint256 re = market.re();
        uint256 rt = market.rt();

        poolManager.initialize(
            key,
            ClogGenuineMath.sqrtPriceX96Of(re, rt)
        );

        hook.launch(key, re, rt);
    }

    function _normalize(
        string memory input
    ) internal pure returns (string memory) {
        bytes memory b = bytes(input);

        if (
            b.length < MIN_TICKER_LENGTH
                || b.length > MAX_TICKER_LENGTH
        ) revert InvalidTickerLength();

        bytes memory out = new bytes(b.length);

        for (uint256 i = 0; i < b.length; i++) {
            uint8 c = uint8(b[i]);

            if (c >= 0x61 && c <= 0x7A) {
                out[i] = bytes1(c - 32);
            } else if (c >= 0x41 && c <= 0x5A) {
                out[i] = bytes1(c);
            } else {
                revert InvalidTickerCharacter();
            }
        }

        return string(out);
    }
}

